假设经济体中共有$N\in \mathbb{N}$个省份，因此每个省份中的家户都有$N$个劳动供给决策，当前省份的家户在时间点对第$j$个省份提供的劳动供给就可以记作$l_{j,t}$。家户的效用函数为CRRA效用函数，则家户的最优化问题可以描述为：
\begin{equation}
	U(c_t,l_{1,t},...,l_{N,t}) = \frac{c_t^{1-\gamma_c}}{1-\gamma_c} -  \sum\limits_{j=1}\limits^{N} { \varphi_j \frac{l_{j,t}^{1+\phi}}{1+\phi} }
\end{equation}

其中$\varphi_j$代表家户去第$j$个省份工作的厌恶程度，$\phi$代表家户弗里茨弹性的倒数。为了便于求解，这里假设家户去不同省份工作造成的效用损失比例不同，但是因为劳动本身无差异，所以不同省份的劳动弹性相同。

\begin{equation}
	\begin{aligned}
		\dot{b} &= r_b b_t + \sum\limits_{j=1}\limits^{N} { w_{j,t} \left(1 - \tau - \sigma_j \right) z_t l_{j,t} } - d_t - \chi(d_t, a_t) - c_t \\
		\dot{a} &= r_a a_t + d_t
	\end{aligned}
\end{equation}

其中$w_{j,t}$为第$j$个省份在时间点$t$提供的平均工资率，$\tau$为全国统一的工资税率，$\sigma_j$为家户去第$j$个省份工作的迁移成本，迁移成本仅和省份之间的距离有关，因此家户在本省工作时迁移成本为0。$d_t$为家户在时间点t的储蓄额，代表家户从流动性资产（通常是现金）账户向非流动性资产账户转入的额度，$d_t<0$则代表家户从非流动性资产账户提取资金。$\chi$代表修改非流动性资产账户的资金转移成本。

参考第三章的省级异质性主体框架算法，通过求解家户效用的最优化问题，可以得到家户的总劳动供给和平均工资率：
\begin{equation}
	\begin{aligned}
		l_{j,t} &= c_t^{-\frac{\gamma_c}{\phi}} \left( w_{j,t} z_t \frac{1 - \tau - \sigma_j}{\varphi_j}\right)^{\frac{1}{\phi}},\ j \in [1,...,N],\\
		l_t & = c_t^{-\frac{\gamma_c}{\phi}} \varphi^{-\frac{1}{1+\phi}} \left[\sum\limits_{j=1}\limits^{N} { \varphi_j \left( w_{j,t} z_t\frac{1 - \tau - \sigma_j}{\varphi_j}\right)^{1+\frac{1}{\phi}}}\right] ^ {\frac{1}{1+\phi}},\\
		w_t &= \varphi^{-\frac{\phi}{1+\phi}} \left[\sum\limits_{j=1}\limits^{N} { \varphi_j \left( w_{j,t} \frac{1 - \tau - \sigma_j}{\varphi_j}\right)^{1+\frac{1}{\phi}}}\right] ^ {\frac{\phi}{1+\phi}},\\
		w_t z_t l_t &= c_t^{\gamma_c} \varphi l_t^{1+\phi} = l_t \varphi^{-\frac{\phi}{1+\phi}} z_t \left[\sum\limits_{j=1}\limits^{N} { \varphi_j \left( w_{j,t} \frac{1 - \tau - \sigma_j}{\varphi_j}\right)^{1+\frac{1}{\phi}}}\right] ^ {\frac{\phi}{1+\phi}}.
	\end{aligned}
\end{equation}

其中$l_t$和$w_t$为本省家户的总劳动供给和总平均工资。

\begin{equation}
	\begin{aligned}
		&Ls^i_t = \sum_{j=1}^{N} L^j_{it} N^j_t, \quad L^j_{it} = \int z^j_t l^j_{it} d g^j_t. \\
		&Ks^i_t = (1-\kappa^i) A^i_{t} N^i_t + \frac{\sum_{j \neq i} \kappa^j A^j_{t} N^j_t}{N-1} + Kg^i_t, \quad A^i_{t} = \int a^i_{t} d g^i_t. \\
		&Y^i_t = Z^i_t (Ks^i_t)^{\alpha^i}(Ls^i_t)^{1-\alpha^i}.
	\end{aligned}
\end{equation}

其中$g^j_t$代表第$j$个省份的家户分布函数，$N^j_t$为该省的人口规模，$\kappa^j$为该省份家户的跨省投资比例，每个省的家户都会均匀购买其余30个省份的非流动性资产。第$i$个省份的劳动供给等同于全国家户对该省的有效劳动供给$L^j_{it} N^j_t$之和，而资本供给等于本省的家户资产与政府资产$Kg^i_t$之和。

第$i$个省份的劳动和资本的边际产量为：
\begin{equation}
	\begin{aligned}
		w^i_t = mc^i_t Z^i_t (1-\alpha^i) \left(\frac{Ks^i_t}{Ls^i_t}\right)^{\alpha^i}, \\
		r^i_{kt} = mc^i_t Z^i_t \alpha^i \left(\frac{Ls^i_t}{Ks^i_t}\right)^{1-\alpha^i}.
	\end{aligned}
\end{equation}

\xsubsection{中央银行和政府部门}{Central Bank and Government Sector}

本章的省级异质性主体新凯恩斯框架中，所有省份接受统一的政府税率与央行。
政府允许拥有盈余项，政府收入和支出分别为：
\begin{equation}
	\begin{aligned}
		GovInc = \sum_{j=1}^{31} \left\{\Pi^i_t \tau^i_{firm} +  Ls^j_t \tau + Kg^j_t r^j_{at}\right\} ,\\
		GovExp = \sum_{j=1}^{31} \left\{ T^j_t + (Y^j_t + B^j_t) r_{b}\right\}
	\end{aligned}
\end{equation}

HANK模型中的政府部门允许财政存在赤字或盈余，其预算约束形式一般为：
\begin{equation}
	T_t + M_t r_b + S_t = L_t w_t \tau_w + \tau_{firm} \Pi_t + Kg_t r_a
\end{equation}

上式左侧为政府支出项，从左到右分别为对家户的转移支付总额、政府债券（也即货币总量）利息和政府盈余，右侧为政府收入项，主要包括工资税收、企业税收和政府投资收益。由于本文主要研究不同地区家户和企业在经济发展中的关联，政府部门在HANK模型中是中性部门，不具有最优化目标。

在HJB方程两侧，对消费和劳动分别求偏导可得一阶条件方程：
\begin{equation}
	\begin{aligned}
		c_t^{-\gamma_c} &= V_b\\
		\varphi_j  l_{j,t}^{\phi} &= V_b w_{j,t} \left(1 - \tau - \sigma_j \right) z_t ,\ j \in [1,N] \\
	\end{aligned}
\end{equation}

上式的共同点是右侧都有值函数的偏导数$V_b$，并且值函数的偏导数必然不等于零，因此可以对劳动的一阶条件进行化简：
\begin{equation} \label{ljt_func}
	l_{j,t}= c_t^{-\frac{\gamma_c}{\phi}} \left( w_{j,t} z_t \frac{1 - \tau - \sigma_j}{\varphi_j}\right)^{\frac{1}{\phi}},\ j \in [1,...,N]
\end{equation}

\begin{equation}
	\begin{aligned}
		w_t z_t l_t &= \sum\limits_{j=1}\limits^{N} w_{j,t} \left(1 - \tau - \sigma_j\right) z_t  l_{j,t} \\
		U(c_t,l_t) &= \frac{c_t^{1-\gamma_c}}{1-\gamma_c} - \varphi \frac{l_t^{1+\phi}}{1+\phi} = 	\frac{c_t^{1-\gamma_c}}{1-\gamma_c} -  \sum\limits_{j=1}\limits^{N} { \varphi_j \frac{l_{j,t}^{1+\phi}}{1+\phi} }
	\end{aligned}
\end{equation}

上面第二个方程中，可以将两侧的消费项消去后得到总劳动供给和各省份劳动供给的替代方程：
\begin{equation}
	\varphi l_t^{1+\phi} = \sum\limits_{j=1}\limits^{N} { \varphi_j  l_{j,t}^{1+\phi} } 
\end{equation}

\begin{equation} \label{lt_func}
	\begin{aligned}
		\varphi l_t^{1+\phi} = \sum\limits_{j=1}\limits^{N} { \varphi_j  l_{j,t}^{1+\phi} }  &= c_t^{-\frac{\gamma_c(1+\phi)}{\phi}} \sum\limits_{j=1}\limits^{N} { \varphi_j \left( w_{j,t} z_t\frac{1 - \tau - \sigma_j}{\varphi_j}\right)^{1+\frac{1}{\phi}}}, \\
		l_t & = c_t^{-\frac{\gamma_c}{\phi}} \varphi^{-\frac{1}{1+\phi}} \left[\sum\limits_{j=1}\limits^{N} { \varphi_j \left( w_{j,t} z_t\frac{1 - \tau - \sigma_j}{\varphi_j}\right)^{1+\frac{1}{\phi}}}\right] ^ {\frac{1}{1+\phi}}
	\end{aligned}

\begin{equation}
	\begin{aligned}
		w_t z_t l_t &= c_t^{\gamma_c} \varphi l_t^{1+\phi} = l_t \varphi^{-\frac{\phi}{1+\phi}} z_t \left[\sum\limits_{j=1}\limits^{N} { \varphi_j \left( w_{j,t} \frac{1 - \tau - \sigma_j}{\varphi_j}\right)^{1+\frac{1}{\phi}}}\right] ^ {\frac{\phi}{1+\phi}},\\
		w_t &= \varphi^{-\frac{\phi}{1+\phi}} \left[\sum\limits_{j=1}\limits^{N} { \varphi_j \left( w_{j,t} \frac{1 - \tau - \sigma_j}{\varphi_j}\right)^{1+\frac{1}{\phi}}}\right] ^ {\frac{\phi}{1+\phi}}
	\end{aligned}
\end{equation}

目前为止，我们已经完成了对家户的总劳动$l_t$和总工资$w_t$的推导，并且总劳动的效用厌恶系数$\varphi$是可以设定的外生参数，后续这个HJB问题的求解就转化成了经典的单劳动供给两资产模型的求解。在求解完成后，每个省份的劳动供给可以由\ref{ljt_func}反推出来。

\begin{equation}
	\begin{aligned}
		w_t z_t l_t &= c_t^{\gamma_c} \varphi l_t^{1+\phi} = l_t \varphi^{\frac{1}{1+\phi}} z_t \left[\sum\limits_{j=1}\limits^{N} { \varphi_j \left( w_{j,t} \frac{1 - \tau - \sigma_j}{\varphi_j}\right)^{1+\frac{1}{\phi}}}\right] ^ {\frac{\phi}{1+\phi}},\\
		w_t &= \varphi^{\frac{1}{1+\phi}} \left[\sum\limits_{j=1}\limits^{N} { \varphi_j \left( w_{j,t} \frac{1 - \tau - \sigma_j}{\varphi_j}\right)^{1+\frac{1}{\phi}}}\right] ^ {\frac{\phi}{1+\phi}}
	\end{aligned}
\end{equation}

